package com.gameaggregator.revenueservice.domain;import jakarta.persistence.*;import java.util.UUID;@Entity @Table(name="revenue_rules") public class RevenueRule{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID contractId;@Column(nullable=false)public UUID gameId;@Column(nullable=false)public String name;@Column(nullable=false)public String status="ACTIVE";protected RevenueRule(){}public RevenueRule(UUID c,UUID g,String n){contractId=c;gameId=g;name=n;}}